describe('Lazy-loaded Components - No Layout Shift', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should load lazy-loaded components smoothly without layout shift', () => {
    // Verify initial state
    cy.get('[data-testid="dashboard-header"]').should('be.visible');
    cy.get('[data-testid="dashboard-sidebar"]').should('be.visible');
    cy.get('[data-testid="dashboard-content"]').should('contain', 'Welcome');

    // Intercept API call for lazy-loaded component
    cy.intercept('GET', '/api/components/dashboard-chart').as('loadChart');

    // Trigger lazy-load
    cy.get('[data-testid="dashboard-chart-trigger"]').click();

    // Wait for lazy-load to complete
    cy.wait('@loadChart');

    // Verify component is now visible without layout shift
    cy.get('[data-testid="dashboard-chart"]').should('be.visible');
    cy.get('[data-testid="dashboard-chart"]').should('contain', 'Data');

    // Verify layout remains stable
    cy.get('[data-testid="dashboard-header"]').should('have.css', 'position', 'static');
    cy.get('[data-testid="dashboard-sidebar"]').should('have.css', 'position', 'static');
    cy.get('[data-testid="dashboard-content"]').should('have.css', 'position', 'static');

    // Verify no layout shift
    cy.get('[data-testid="dashboard-chart"]').should('not.have.css', 'transform');
    cy.get('[data-testid="dashboard-chart"]').should('not.have.css', 'translateX');
    cy.get('[data-testid="dashboard-chart"]').should('not.have.css', 'translateY');

    // Verify smooth transition
    cy.get('[data-testid="dashboard-chart"]').should('have.css', 'opacity', '1');
    cy.get('[data-testid="dashboard-chart"]').should('not.have.css', 'opacity', '0');

    // Verify no performance issues
    cy.get('[data-testid="dashboard-chart"]').should('have.css', 'transition', 'all 0.3s ease');
  });

  it('should handle failed lazy-load without layout shift', () => {
    // Trigger lazy-load
    cy.get('[data-testid="dashboard-chart-trigger"]').click();

    // Simulate failed API call
    cy.intercept('GET', '/api/components/dashboard-chart', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('failedLoadChart');

    // Wait for failed load
    cy.wait('@failedLoadChart');

    // Verify error state is displayed
    cy.get('[data-testid="dashboard-chart-error"]').should('be.visible');
    cy.get('[data-testid="dashboard-chart-error"]').should('contain', 'Failed to load');

    // Verify layout remains stable
    cy.get('[data-testid="dashboard-header"]').should('have.css', 'position', 'static');
    cy.get('[data-testid="dashboard-sidebar"]').should('have.css', 'position', 'static');
    cy.get('[data-testid="dashboard-content"]').should('have.css', 'position', 'static');

    // Verify no layout shift
    cy.get('[data-testid="dashboard-chart-error"]').should('not.have.css', 'transform');
    cy.get('[data-testid="dashboard-chart-error"]').should('not.have.css', 'translateX');
    cy.get('[data-testid="dashboard-chart-error"]').should('not.have.css', 'translateY');

    // Verify error message is clear and user-friendly
    cy.get('[data-testid="dashboard-chart-error"]').should('contain', 'Please try again later');

    // Verify error state is accessible
    cy.get('[data-testid="dashboard-chart-error"]').should('be.visible');
    cy.get('[data-testid="dashboard-chart-error"]').should('be.displayed');
  });
});
